def manifest(*,feature_id:str,contract_version:str,scale:str)->dict[str,Any]:return {"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":contract_version,"owner_crate":"worldgen","consumers":["imaging core scientist","interpretation operator","research program lead"],"behavior":f"run approval-bounded interpretation actions for {scale}","value":"turns qualified statistical evidence into a replayable copilot decision without hidden effects","input_schema":"InterpretationCopilotRequest1@1","output_schema":"InterpretationCopilotReceipt1@1","effects":["invoke:bounded-interpretation-tool","block:unsafe-release"],"permissions":["invoke:declared-interpretation-tool"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":PRECLINICAL_BOUNDARY}
